function validate(input) {
  const [{ Project = [], Employee = [] }] = input;
  const employees = new Set(), pairs = new Set();
  for (const [id, , years] of Employee) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (employees.has(id)) return `employee_id ${id} appears twice in Employee.`;
    if (years === null || years < 0) return `Employee ${id} needs a non-negative experience_years.`;
    employees.add(id);
  }
  for (const [project, employee] of Project) {
    if (project === null || employee === null) return 'Project rows need both ids.';
    const key = `${project}:${employee}`;
    if (pairs.has(key)) return `(${project}, ${employee}) appears twice in Project.`;
    if (!employees.has(employee)) return `Project ${project} names unknown employee ${employee}.`;
    pairs.add(key);
  }
  return null;
}

