function generate(rand, size) {
  const names = ['Khaled', 'Ali', 'John', 'Doe', 'Ana', 'Lee', 'Kim', 'Ravi'];
  const small = size === 'small';
  const employeeCount = small ? Math.floor(rand() * 9) : 1000;
  const Employee = [], Project = [];
  for (let id = 1; id <= employeeCount; id++) {
    Employee.push([id, names[Math.floor(rand() * names.length)], small ? Math.floor(rand() * 5) : Math.floor(rand() * 41)]);
  }
  if (employeeCount === 0) return [{ Project, Employee }];
  // Each project gets a random set of distinct employees; some employees end up on no project.
  const projectCount = small ? 1 + Math.floor(rand() * 3) : 300;
  const target = small ? Math.floor(rand() * 9) : 2000;
  const seen = new Set();
  for (let tries = 0; Project.length < target && tries < target * 4; tries++) {
    const project = 1 + Math.floor(rand() * projectCount), employee = 1 + Math.floor(rand() * employeeCount);
    if (seen.has(`${project}:${employee}`)) continue;
    seen.add(`${project}:${employee}`);
    Project.push([project, employee]);
  }
  return [{ Project, Employee }];
}
